 "content": "def transform(grid):
    g=[r[:] for r in grid]
    h,w=len(g),len(g[0])
    # Connected 5-frame with horizontal and vertical arms: input markers attached
    # to the outer sides seed stripes that propagate along each arm.
    # Horizontal arm is row 1, columns 0..4; left-side color marks propagate
    # horizontally across its length.
    for r in range(h):
        if g[r][0] not in (0,5) and any(g[1][c]==5 for c in range(5)):
            g[r][:5]=[g[r][0]]*5
    # Vertical arm at column 6: top-side color at row 1, column 6 is 5;
    # right-side seed pattern at the bottom is repeated upward in aligned cells.
    # The input seed is the three-cell row beneath the endpoint; extend it upward
    # to rows where the vertical 5 segment is present.
    c=6
    if sum(g[r][c]==5 for r in range(h))>=3:
        seed=next((r for r in range(h) if any(g[r][j] not in (0,5) for j in range(c+1,w))),None)
        if seed is not None:
            pat=g[seed][c+1:]
            for r in range(seed):
                if g[r][c]==5: g[r][c+1:]=pat
    return g
